import os
import subprocess
from typing import Any, Dict, List


DOCS_DIR = "/workspace/docs"
CONVERTED_DIR = "/workspace/converted"


def _option_to_args(key: str, value: Any) -> List[str]:
    """Convert an option key/value pair into pandoc CLI arguments."""
    option = key.replace("_", "-")

    # Common alias: the output extension/format should also tell pandoc which
    # writer to use. The caller-facing requirement reserves "format" for the
    # output extension, so handle it specially rather than emitting --format.
    if key == "format":
        if value in (None, False):
            return []
        return ["-t", str(value)]

    if len(option) == 1:
        flag = f"-{option}"
    else:
        flag = f"--{option}"

    if isinstance(value, bool):
        return [flag] if value else []

    if value is None:
        return []

    if isinstance(value, (list, tuple, set)):
        args: List[str] = []
        for item in value:
            if item is not None:
                args.extend([flag, str(item)])
        return args

    return [flag, str(value)]


def convert_document(filename: str, extra_options: Dict[str, Any] = None) -> bool:
    """
    Converts document from /workspace/docs/<filename> to
    /workspace/converted/<basename>.<format>.

    Invokes pandoc using subprocess.run([...]) with extra CLI options and returns
    True only when pandoc succeeds and the expected output file exists.
    """
    if not isinstance(filename, str) or not filename:
        return False

    extra_options = extra_options or {}
    if not isinstance(extra_options, dict):
        return False

    output_format = str(extra_options.get("format", "html") or "html")
    basename = os.path.splitext(os.path.basename(filename))[0]
    if not basename:
        return False

    docs_dir = os.path.abspath(DOCS_DIR)
    converted_dir = os.path.abspath(CONVERTED_DIR)
    input_path = os.path.abspath(os.path.join(docs_dir, filename))
    output_path = os.path.abspath(os.path.join(converted_dir, f"{basename}.{output_format}"))

    # Ensure the requested paths stay inside the intended workspace folders.
    if os.path.commonpath([docs_dir, input_path]) != docs_dir:
        return False
    if os.path.commonpath([converted_dir, output_path]) != converted_dir:
        return False
    if not os.path.isfile(input_path):
        return False

    os.makedirs(converted_dir, exist_ok=True)

    command: List[str] = ["pandoc", input_path, "-o", output_path]
    for key, value in extra_options.items():
        command.extend(_option_to_args(str(key), value))

    try:
        result = subprocess.run(command, check=False)
    except (OSError, ValueError):
        return False

    return result.returncode == 0 and os.path.exists(output_path)
